export function t(langCode, key, vars) {
  const langStrings = STRINGS[langCode] || STRINGS.en;
  let str = langStrings[key] !== undefined ? langStrings[key] : STRINGS.en[key];
  if (str === undefined) str = key;
  if (vars)
    for (const varKey in vars) {
      str = str.split('{' + varKey + '}').join(String(vars[varKey]));
    }
  return str;
}
